#include <bits/stdc++.h>
using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size();
    long long answer = 0;
    // Expand around every character (odd length) and every gap (even length).
    for (int c = 0; c < n; c++) {
        for (int l = c, r = c; l >= 0 && r < n && s[l] == s[r]; l--, r++) answer++;
        for (int l = c, r = c + 1; l >= 0 && r < n && s[l] == s[r]; l--, r++) answer++;
    }
    printf("%lld\n", answer);
}

import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        String s = new BufferedReader(new InputStreamReader(System.in)).readLine().trim();
        int n = s.length();
        long answer = 0;
        // Expand around every character (odd length) and every gap (even length).
        for (int c = 0; c < n; c++) {
            for (int l = c, r = c; l >= 0 && r < n && s.charAt(l) == s.charAt(r); l--, r++) answer++;
            for (int l = c, r = c + 1; l >= 0 && r < n && s.charAt(l) == s.charAt(r); l--, r++) answer++;
        }
        System.out.println(answer);
    }
}

package main

import "fmt"

func main() {
	var s string
	fmt.Scan(&s)
	n := len(s)
	answer := 0
	// Expand around every character (odd length) and every gap (even length).
	for c := 0; c < n; c++ {
		for l, r := c, c; l >= 0 && r < n && s[l] == s[r]; l, r = l-1, r+1 {
			answer++
		}
		for l, r := c, c+1; l >= 0 && r < n && s[l] == s[r]; l, r = l-1, r+1 {
			answer++
		}
	}
	fmt.Println(answer)
}
